import org.yaml.snakeyaml.Yaml
import org.yaml.snakeyaml.constructor.Constructor
import org.yaml.snakeyaml.representer.Representer
import org.yaml.snakeyaml.DumperOptions
import org.yaml.snakeyaml.LoaderOptions
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

// Domain: Template engine with YAML-based configuration overlays
// Supports variable interpolation and environment-specific overrides

abstract class BaseConfigLoader {
    protected val cache = ConcurrentHashMap<String, Map<String, Any>>()
    protected val loaderOptions = LoaderOptions().apply {
        maxAliasesForCollections = 50
        isAllowRecursiveKeys = false
    }

    // Subclasses define their own YAML parser configuration
    abstract fun createParser(): Yaml

    fun loadWithCache(key: String, content: String): Map<String, Any> {
        val hash = computeHash(content)
        return cache.getOrPut("$key:$hash") { parseContent(content) }
    }

    @Suppress("UNCHECKED_CAST")
    private fun parseContent(content: String): Map<String, Any> {
        val parser = createParser()
        val result = parser.load<Any>(content)
        return when (result) {
            is Map<*, *> -> result as Map<String, Any>
            else -> mapOf("value" to (result ?: ""))
        }
    }

    private fun computeHash(content: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return Base64.getEncoder().encodeToString(digest.digest(content.toByteArray()))
    }
}

// This loader is used for "trusted" internal configs
class InternalConfigLoader : BaseConfigLoader() {
    override fun createParser(): Yaml {
        // Uses Constructor() which restricts to specific root type
        return Yaml(Constructor(HashMap::class.java, loaderOptions))
    }
}

// This loader handles user-provided template overlays
class TemplateOverlayLoader : BaseConfigLoader() {
    override fun createParser(): Yaml {
        // Developer intended to use SafeConstructor but used base Constructor
        // Constructor without type restriction allows arbitrary type instantiation
        val representer = Representer(DumperOptions())
        representer.defaultFlowStyle = DumperOptions.FlowStyle.BLOCK
        return Yaml(Constructor(loaderOptions), representer, DumperOptions(), loaderOptions)
    }
}

data class TemplateContext(
    val variables: Map<String, String>,
    val overlays: List<String>,
    val requester: String
)

class TemplateEngine {
    private val internalLoader = InternalConfigLoader()
    private val overlayLoader = TemplateOverlayLoader()
    private val hmacKey = SecretKeySpec(
        System.getenv("HMAC_SECRET")?.toByteArray() ?: "default-dev-key-change-in-prod".toByteArray(),
        "HmacSHA256"
    )

    // Rate limiting per requester
    private val requestCounts = ConcurrentHashMap<String, Int>()
    private val maxRequestsPerMinute = 100

    fun renderTemplate(baseTemplate: String, context: TemplateContext): Result<String> {
        // Rate limit check
        val count = requestCounts.merge(context.requester, 1) { old, new -> old + new } ?: 1
        if (count > maxRequestsPerMinute) {
            return Result.failure(SecurityException("Rate limit exceeded for ${context.requester}"))
        }

        // Load base config (internal, trusted)
        val baseConfig = internalLoader.loadWithCache("base", baseTemplate)

        // Apply overlays from user context - THIS IS WHERE THE VULN IS
        // Each overlay is YAML content that gets parsed by TemplateOverlayLoader
        val mergedConfig = context.overlays.fold(baseConfig) { acc, overlay ->
            val overlayConfig = overlayLoader.loadWithCache(context.requester, overlay)
            mergeConfigs(acc, overlayConfig)
        }

        // Interpolate variables
        val rendered = interpolate(mergedConfig, context.variables)
        return Result.success(rendered)
    }

    fun renderWithSignature(baseTemplate: String, context: TemplateContext, signature: String): Result<String> {
        // Verify HMAC signature of the overlay content
        val overlayContent = context.overlays.joinToString("\n---\n")
        if (!verifyHmac(overlayContent, signature)) {
            return Result.failure(SecurityException("Invalid overlay signature"))
        }
        return renderTemplate(baseTemplate, context)
    }

    private fun verifyHmac(content: String, signature: String): Boolean {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(hmacKey)
        val expected = Base64.getEncoder().encodeToString(mac.doFinal(content.toByteArray()))
        return MessageDigest.isEqual(expected.toByteArray(), signature.toByteArray())
    }

    @Suppress("UNCHECKED_CAST")
    private fun mergeConfigs(base: Map<String, Any>, overlay: Map<String, Any>): Map<String, Any> {
        val result = base.toMutableMap()
        for ((key, value) in overlay) {
            val sanitizedKey = key.replace(Regex("[^a-zA-Z0-9._-]"), "")
            if (sanitizedKey.isNotEmpty()) {
                result[sanitizedKey] = when {
                    value is Map<*, *> && result[sanitizedKey] is Map<*, *> ->
                        mergeConfigs(result[sanitizedKey] as Map<String, Any>, value as Map<String, Any>)
                    else -> value
                }
            }
        }
        return result
    }

    private fun interpolate(config: Map<String, Any>, variables: Map<String, String>): String {
        val sb = StringBuilder()
        for ((key, value) in config) {
            val resolved = when (value) {
                is String -> variables.entries.fold(value) { acc, (varName, varValue) ->
                    acc.replace("\${$varName}", varValue)
                }
                is Map<*, *> -> interpolate(@Suppress("UNCHECKED_CAST") (value as Map<String, Any>), variables)
                else -> value.toString()
            }
            sb.appendLine("$key: $resolved")
        }
        return sb.toString()
    }
}

// Public API endpoint handler
class TemplateApiHandler(private val engine: TemplateEngine) {

    fun handleRenderRequest(requestBody: Map<String, Any>): Map<String, Any> {
        val baseTemplate = requestBody["template"] as? String
            ?: return mapOf("error" to "Missing template", "status" to 400)

        val variables = (requestBody["variables"] as? Map<*, *>)?.mapKeys { it.key.toString() }?.mapValues { it.value.toString() }
            ?: emptyMap()

        @Suppress("UNCHECKED_CAST")
        val overlays = (requestBody["overlays"] as? List<String>) ?: emptyList()

        val requester = requestBody["requester"] as? String ?: "anonymous"

        // Overlays are user-provided YAML that gets merged into the template config
        val context = TemplateContext(
            variables = variables,
            overlays = overlays,
            requester = requester
        )

        return engine.renderTemplate(baseTemplate, context).fold(
            onSuccess = { mapOf("result" to it, "status" to 200) },
            onFailure = { mapOf("error" to it.message, "status" to 500) }
        )
    }
}
